进程管理应用示例：fork()和exec()

// usr/src/bin/forkexec.rs
pub fn main() - i32 {
    println!("pid {}: parent start forking ...", getpid());
    let pid = fork();  // 创建子进程
    if pid == 0 {
        // 子进程
        println!("pid {}: forked child start execing helloworld app ... ", getpid());
        exec("helloworld");  // 执行helloworld程序
        100
    } else {
        // 父进程
        let mut exitcode: i32 = 0;
        println!("pid {}: ready waiting child ...", getpid());
        asserteq!(pid, wait(&mut exitcode)); //确认等待的子进程PID
        asserteq!(exitcode, 0);  //确认退出码是0
        println!("pid {}: got child info:: pid {}, exit code: {}", getpid() , pid, exitcode);
        0
    }
}

